import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class PublicExamplesTest{static String capture(Runnable action){PrintStream previous=System.out,oldErr=System.err;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);System.setErr(out);action.run();}finally{System.setOut(previous);System.setErr(oldErr);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void initialEmptyEvenWithPreloadedStorageAndTwoTypes(){for(int kind=0;kind<2;kind++){Object q=TaskBinding.create(kind,2);assertFalse(capture(()->assertNull(TaskBinding.get(q))).isBlank());Object a=kind==0?"A":1,b=kind==0?"B":2,c=kind==0?"C":3;TaskBinding.put(q,a);TaskBinding.put(q,b);assertFalse(capture(()->TaskBinding.put(q,c)).isBlank());assertSame(a,TaskBinding.get(q));TaskBinding.put(q,c);assertSame(b,TaskBinding.get(q));assertSame(c,TaskBinding.get(q));assertFalse(capture(()->assertNull(TaskBinding.get(q))).isBlank());}}}
